"""Round-5 theory additions for slide topics the bank lacked (DML, DDL, views, routines, CHECK). MySQL 8.0.28.
Examples run on the build server in ONE connection each and must leave no persistent change (TEMPORARY tables, ROLLBACK, or create-then-drop)."""

def T(number, question, answer, tags, example, pattern='computed'):
    return dict(id='TH4-%03d' % number, question=question, answer=answer,
                tags=tags.split('|'), examples=[example] if example else [],
                pattern=pattern, mistakes=[])

THEORY4 = [
 T(1, 'What are the forms of INSERT and when is each used?',
   'INSERT INTO t VALUES (...) needs a value for every column in table order, so it breaks when a column is added. INSERT INTO t (c1, c2) VALUES (...) names the columns; omitted columns get their default or NULL, which is how partial rows are inserted. A multi-row VALUES list and INSERT ... SELECT insert many rows in one statement.',
   'insert|values|column list|partial row|insert select',
   "CREATE TEMPORARY TABLE th4_t (id INT PRIMARY KEY, name VARCHAR(20), note VARCHAR(20) DEFAULT 'none'); INSERT INTO th4_t (id, name) VALUES (1, 'a'), (2, 'b'); INSERT INTO th4_t SELECT ID + 10, Company, NULL FROM shippers; SELECT * FROM th4_t ORDER BY id;",
   'select_filter'),
 T(2, 'How do you run UPDATE and DELETE safely?',
   'Write the WHERE clause first, because UPDATE or DELETE without one changes every row. Run a SELECT with the same WHERE to preview the affected rows, then run the change inside START TRANSACTION so ROLLBACK can undo a mistake. MySQL rejects a subquery that reads the table being modified (error 1093) unless it is wrapped in a derived table.',
   'update|delete|where|transaction|safe updates|error 1093',
   "START TRANSACTION; UPDATE products SET `List Price` = `List Price` * 1.1 WHERE Category = 'Beverages'; SELECT ROW_COUNT(); ROLLBACK;",
   'select_filter'),
 T(3, 'CREATE TABLE ... AS SELECT versus CREATE TABLE ... LIKE: what is copied?',
   'CREATE TABLE t2 AS SELECT ... creates columns from the query and copies the selected rows, but not primary keys, indexes or AUTO_INCREMENT. CREATE TABLE t2 LIKE t1 copies the full structure including keys and indexes but no rows. To clone a table with data, run LIKE and then INSERT INTO t2 SELECT * FROM t1.',
   'create table as select|create table like|ctas|copy table',
   "CREATE TEMPORARY TABLE th4_copy AS SELECT * FROM shippers; CREATE TEMPORARY TABLE th4_like LIKE shippers; SELECT (SELECT COUNT(*) FROM th4_copy), (SELECT COUNT(*) FROM th4_like);",
   'select_filter'),
 T(4, 'How do ALTER TABLE ADD, MODIFY and DROP COLUMN work, and what goes wrong with NOT NULL?',
   'ALTER TABLE t ADD COLUMN c type adds a column, MODIFY COLUMN changes its type or nullability, and DROP COLUMN removes it together with its data. Adding a NOT NULL column to a populated table needs a DEFAULT, otherwise existing rows get an implicit value or the statement fails depending on sql_mode. ALTER TABLE is DDL: it commits immediately and cannot be rolled back.',
   'alter table|add column|modify column|drop column|not null',
   "CREATE TEMPORARY TABLE th4_a (id INT); INSERT INTO th4_a VALUES (1), (2); ALTER TABLE th4_a ADD COLUMN flag TINYINT NOT NULL DEFAULT 1; ALTER TABLE th4_a MODIFY COLUMN flag SMALLINT NOT NULL DEFAULT 0; ALTER TABLE th4_a DROP COLUMN flag; SELECT * FROM th4_a;",
   'select_filter'),
 T(5, 'What is a view, and when can you update through it?',
   'A view stores a SELECT definition, not data; every query on the view re-runs that SELECT. A view is updatable only when each row maps to one base row, so DISTINCT, GROUP BY, aggregates, UNION and window functions make it read-only. WITH CHECK OPTION stops an UPDATE or INSERT through the view from creating rows that the view itself would not show.',
   'view|create view|updatable view|with check option',
   "CREATE VIEW th4_view AS SELECT ID, Company FROM shippers WHERE ID < 3 WITH CHECK OPTION; SELECT COUNT(*) FROM th4_view; DROP VIEW th4_view;",
   'subquery'),
 T(6, 'How do you create a user-defined function in MySQL and why is DELIMITER needed?',
   'CREATE FUNCTION name(params) RETURNS type DETERMINISTIC RETURN expression defines a scalar function that can be used inside any SELECT. A body with several statements uses BEGIN ... END, and the client command DELIMITER (for example $$) changes the statement terminator so the semicolons inside the body do not end the CREATE early. DELIMITER is a mysql client command, not SQL, and with binary logging enabled the function must be declared DETERMINISTIC or NO SQL.',
   'create function|user defined function|delimiter|deterministic',
   "DROP FUNCTION IF EXISTS th4_full_name; CREATE FUNCTION th4_full_name(first_name VARCHAR(50), last_name VARCHAR(50)) RETURNS VARCHAR(101) DETERMINISTIC RETURN CONCAT(first_name, ' ', last_name); SELECT th4_full_name(`First Name`, `Last Name`) FROM employees ORDER BY ID LIMIT 1; DROP FUNCTION th4_full_name;",
   'string_funcs'),
 T(7, 'What is a trigger, and what are NEW and OLD?',
   'A trigger is a stored program that runs automatically BEFORE or AFTER an INSERT, UPDATE or DELETE on one table. NEW holds the incoming row (INSERT, UPDATE) and OLD the previous row (UPDATE, DELETE); a BEFORE trigger may change NEW or reject the row with SIGNAL. Triggers fire once per row and cannot be created on views or temporary tables.',
   'trigger|before insert|new and old|signal',
   "CREATE TABLE th4_trigger_t (id INT, qty INT); CREATE TRIGGER th4_before_ins BEFORE INSERT ON th4_trigger_t FOR EACH ROW SET NEW.qty = GREATEST(NEW.qty, 0); INSERT INTO th4_trigger_t VALUES (1, -5), (2, 7); SELECT * FROM th4_trigger_t ORDER BY id; DROP TABLE th4_trigger_t;",
   'select_filter'),
 T(8, 'How do stored procedures use IN, OUT and CALL?',
   'CREATE PROCEDURE name(IN a INT, OUT b INT) defines reusable code that is run with CALL name(...), unlike a function that is used inside an expression. IN passes a value in, OUT returns a value through a session variable such as @result, and INOUT does both. A procedure can contain several statements, control flow and result sets, but cannot be used inside SELECT.',
   'stored procedure|call|in out parameters|create procedure',
   "DROP PROCEDURE IF EXISTS th4_order_count; CREATE PROCEDURE th4_order_count(IN employee INT, OUT total INT) SELECT COUNT(*) INTO total FROM orders WHERE `Employee ID` = employee; CALL th4_order_count(1, @result); SELECT @result; DROP PROCEDURE th4_order_count;",
   'select_filter'),
 T(9, 'Is a CHECK constraint enforced in MySQL 8.0.28?',
   'Yes: since MySQL 8.0.16 CHECK constraints are enforced, so a row that makes the condition false is rejected, while a condition that evaluates to NULL is accepted. Before 8.0.16 the clause was parsed and silently ignored, which is why older notes say MySQL has no CHECK. Add one with CREATE TABLE ... CHECK (condition) or ALTER TABLE ... ADD CONSTRAINT name CHECK (condition).',
   'check constraint|8.0.16|constraint|validation',
   "CREATE TABLE th4_check_t (id INT PRIMARY KEY, price DECIMAL(10,2), CONSTRAINT th4_price_ck CHECK (price >= 0)); INSERT INTO th4_check_t VALUES (1, 5), (2, NULL); SELECT COUNT(*) FROM th4_check_t; DROP TABLE th4_check_t;",
   'null_handling'),
]
